// New defaults dock to screen corners; deliberate dragged positions remain unchanged.
const previousCleanControls=cleanControls;
defaultControls=function(hand='right'){return{hand,move:{x:hand==='left'?1:0,y:1},attack:{x:hand==='left'?0:1,y:1}}};
cleanControls=function(raw){const layout=previousCleanControls(raw),oldMove=layout.hand==='left'?.88:.12,oldAttack=1-oldMove;const near=(a,b)=>Math.abs(a-b)<.00001;if(near(layout.move.x,oldMove)&&near(layout.attack.x,oldAttack)&&near(layout.move.y,.8)&&near(layout.attack.y,.8))return defaultControls(layout.hand);return layout};
const freePositionLayout=applyLayout;
applyLayout=function(root,layout=cleanControls(profile.controls)){if(!root)return;const def=defaultControls(layout.hand),docked=layout.move.x===def.move.x&&layout.attack.x===def.attack.x&&layout.move.y===1&&layout.attack.y===1&&!root.classList.contains('control-editor');root.classList.toggle('corner-layout',docked);if(!docked){freePositionLayout(root,layout);clearMovementGeometry();return}root.dataset.hand=layout.hand;for(const[key,selector]of [['move','.movement-hud'],['attack','.battle-actions']]){const item=root.querySelector(selector);if(!item)continue;const left=layout[key].x===0;item.style.left=left?'max(12px, env(safe-area-inset-left))':'auto';item.style.right=left?'auto':'max(12px, env(safe-area-inset-right))';item.style.top='auto';item.style.bottom='max(12px, env(safe-area-inset-bottom))';item.style.transform='none'}clearMovementGeometry()};
const cornerEditor=controlEditor;controlEditor=function(){cornerEditor();document.querySelector('#control-editor')?.insertAdjacentHTML('afterend','<p class="notice">Default controls sit at the bottom screen corners. Choose Reset positions, then Set & save to restore them.</p>')};
applyBattleControls();
